def _config_file(tmp: str, *, pipeline="hsv_detection") -> str:
    path = Path(tmp) / "config.json"
    path.write_text(
        json.dumps(
            {
                "admin": True,
                "camera_configs": {
                    "cam": {
                        "name": "cam",
                        "camera_type": "opencv",
                        "source": 0,
                        "pipeline": {"name": pipeline, "settings": {}},
                    }
                },
                "plugins": {
                    "trackers": {},
                    "utilities": {},
                    "frame_processors": {},
                },
            }
        )
    )
    return str(path)


def _client(path: str):
    config = iSpyConfig(file_path=path, create=False)
    return config, create_app(cameras=[], config=config).flask_app.test_client()


