    def test_graph_contains_real_schemas_and_required_metadata(self):
        with tempfile.TemporaryDirectory() as tmp:
            _config, client = _client(_config_file(tmp, pipeline="object_detection"))
            response = client.get("/api/editor/graph")
            self.assertEqual(response.status_code, 200)
            data = response.get_json()
            self.assertTrue(data["ok"])
            nodes = {node["id"]: node for node in data["graph"]["nodes"]}
            camera = nodes["camera:cam"]
            pipeline = nodes["pipeline:cam"]
            self.assertEqual(camera["type"], "camera")
            self.assertIn("source", camera["schema"])
            self.assertEqual(pipeline["plugin"], "object_detection")
            self.assertIn("vision_model", pipeline["schema"])
            self.assertIn("vision_model", pipeline["required"])
            self.assertIn("vision_model", pipeline["completion"]["required"])
            self.assertEqual(data["palette"]["pipelines"][0]["type"], "pipeline")
            self.assertTrue(
                any(item["name"] == "FRC/object_tracker" for item in data["palette"]["trackers"])
            )
            palette_names = {
                item["name"].lower()
                for group in (
                    data["palette"]["trackers"],
                    data["palette"]["utilities"],
                )
                for item in group
            }
            self.assertNotIn("rollback", palette_names)
            self.assertNotIn("roll_back", palette_names)

